changeSet.sql:
alter table regel add constraint regel_typ_ck
    check (typ in ('PFLICHT_WENN', 'EINDEUTIG', 'FOLGE', 'ERWARTET'));
alter table regel add constraint regel_parameter_ck
    check (jsonb_typeof(parameter) = 'object');
alter table regel add constraint regel_schwere_ck
    check (schwere in ('FEHLER', 'WARNUNG'));
alter table regel add constraint regel_code_ck
    check (code ~ '^[a-z][a-z0-9_]{0,39}$');
